// swift-tools-version: 6.0
// libarchive with its compression libraries, built from vendored upstream sources.
// See VERSION for versions, sources and what was left out. Only the module.modulemap files
// and Sources/CArchive/libarchive/config.h (generated by libarchive's CMake on macOS) are ours.
import PackageDescription

let lzmaDefines: [CSetting] = [
    "HAVE_ARM64_CRC32", "HAVE_CHECK_CRC32", "HAVE_CHECK_CRC64", "HAVE_CHECK_SHA256",
    "HAVE_CLOCK_GETTIME", "HAVE_CLOCK_MONOTONIC", "HAVE_DECODERS", "HAVE_ENCODERS",
    "HAVE_DECODER_ARM", "HAVE_DECODER_ARM64", "HAVE_DECODER_ARMTHUMB", "HAVE_DECODER_DELTA",
    "HAVE_DECODER_IA64", "HAVE_DECODER_LZMA1", "HAVE_DECODER_LZMA2", "HAVE_DECODER_POWERPC",
    "HAVE_DECODER_RISCV", "HAVE_DECODER_SPARC", "HAVE_DECODER_X86",
    "HAVE_ENCODER_ARM", "HAVE_ENCODER_ARM64", "HAVE_ENCODER_ARMTHUMB", "HAVE_ENCODER_DELTA",
    "HAVE_ENCODER_IA64", "HAVE_ENCODER_LZMA1", "HAVE_ENCODER_LZMA2", "HAVE_ENCODER_POWERPC",
    "HAVE_ENCODER_RISCV", "HAVE_ENCODER_SPARC", "HAVE_ENCODER_X86",
    "HAVE_FUNC_ATTRIBUTE_CONSTRUCTOR", "HAVE_INTTYPES_H", "HAVE_LZIP_DECODER",
    "HAVE_MF_BT2", "HAVE_MF_BT3", "HAVE_MF_BT4", "HAVE_MF_HC3", "HAVE_MF_HC4",
    "HAVE_STDBOOL_H", "HAVE_STDINT_H", "HAVE_SYSCTLBYNAME", "HAVE_SYS_PARAM_H",
    "HAVE__BOOL", "HAVE___BUILTIN_ASSUME_ALIGNED", "HAVE___BUILTIN_BSWAPXX",
    "MYTHREAD_POSIX", "NDEBUG", "TUKLIB_CPUCORES_SYSCTL", "TUKLIB_FAST_UNALIGNED_ACCESS",
    "TUKLIB_PHYSMEM_SYSCONF", "_DARWIN_C_SOURCE",
].map { CSetting.define($0) } + [
    .define("HAVE_VISIBILITY", to: "0"),
    .define("TUKLIB_SYMBOL_PREFIX", to: "lzma_"),
    .define("PACKAGE_NAME", to: "\"XZ Utils\""),
    .define("PACKAGE_BUGREPORT", to: "\"xz@tukaani.org\""),
    .define("PACKAGE_URL", to: "\"https://tukaani.org/xz/\""),
] + ["api", "common", "check", "lz", "rangecoder", "lzma", "delta", "simple"].map {
    CSetting.headerSearchPath("src/liblzma/\($0)")
} + [.headerSearchPath("src/common"), .unsafeFlags(["-O2", "-w"])]

let package = Package(
    name: "libarchive",
    platforms: [.macOS("27.0")],
    products: [
        .library(name: "CArchive", targets: ["CArchive"]),
    ],
    targets: [
        .target(
            name: "CZstd",
            exclude: ["LICENSE"],
            sources: ["lib/common", "lib/compress", "lib/decompress"],
            publicHeadersPath: "lib",
            cSettings: [
                .define("ZSTD_DISABLE_ASM"),
                .define("ZSTD_MULTITHREAD"),
                .define("ZSTD_LEGACY_SUPPORT", to: "0"),
                .define("XXH_NAMESPACE", to: "ZSTD_"),
                .unsafeFlags(["-O3", "-w"]),
            ]
        ),
        .target(
            name: "CLZ4",
            exclude: ["LICENSE"],
            sources: ["lib/lz4.c", "lib/lz4hc.c", "lib/lz4frame.c", "lib/xxhash.c"],
            publicHeadersPath: "lib",
            cSettings: [
                .define("XXH_NAMESPACE", to: "LZ4_"),
                .unsafeFlags(["-O3", "-w"]),
            ]
        ),
        .target(
            name: "CLZMA",
            exclude: ["COPYING", "COPYING.0BSD"],
            sources: ["src/common"] + ["check", "common", "delta", "lz", "lzma", "rangecoder", "simple"].map { "src/liblzma/\($0)" },
            publicHeadersPath: "src/liblzma/api",
            cSettings: lzmaDefines
        ),
        .target(
            name: "CArchive",
            dependencies: ["CZstd", "CLZ4", "CLZMA"],
            exclude: ["COPYING"],
            sources: ["libarchive"],
            publicHeadersPath: "include",
            cSettings: [
                .define("HAVE_CONFIG_H"),
                .define("LIBARCHIVE_STATIC"),
                .define("__LIBARCHIVE_ENABLE_VISIBILITY"),
                .headerSearchPath("libarchive"),
                .unsafeFlags(["-O2", "-w", "-fvisibility=hidden"]),
            ],
            linkerSettings: [
                .linkedLibrary("z"), .linkedLibrary("bz2"),
                .linkedLibrary("iconv"), .linkedLibrary("xml2"),
            ]
        ),
        .testTarget(name: "CArchiveTests", dependencies: ["CArchive"]),
    ]
)
